do $$ begin if not exists (select 1 from pg_enum where enumtypid = (select oid from pg_type where typname = 'app_permission' and typnamespace = (select oid from pg_namespace where nspname = 'rbac')) and enumlabel = 'astro.read') then alter type rbac.app_permission add value 'astro.read'; alter type rbac.app_permission add value 'astro.create'; end if; end$$;
